    public void onClientTick(ClientTick event)
    {
        if (profileReloadRetryPending
            && !profileReloadPending
            && System.nanoTime() >= nextProfileReloadRetryNanos)
        {
            reloadAllChunks();
            return;
        }
        updateContextState();
    }

