    private List<String> getVisibleSceneChunkKeys()
    {
        WorldView worldView = client.getTopLevelWorldView();
        if (client.getLocalPlayer() == null || worldView == null)
        {
            return Collections.emptyList();
        }

        int plane = worldView.getPlane();
        if (visibleSceneChunkCacheWorldView == worldView
            && visibleSceneChunkCacheBaseX == worldView.getBaseX()
            && visibleSceneChunkCacheBaseY == worldView.getBaseY()
            && visibleSceneChunkCachePlane == plane)
        {
            return visibleSceneChunkCacheKeys;
        }

        Set<String> visibleKeys = new HashSet<>();
        addPlayerNearbySceneChunkKeys(visibleKeys);
        addLoadedSceneChunkKeys(worldView, visibleKeys);

        visibleSceneChunkCacheWorldView = worldView;
        visibleSceneChunkCacheBaseX = worldView.getBaseX();
        visibleSceneChunkCacheBaseY = worldView.getBaseY();
        visibleSceneChunkCachePlane = plane;
        visibleSceneChunkCacheKeys.clear();
        visibleSceneChunkCacheKeys.addAll(visibleKeys);
        return visibleSceneChunkCacheKeys;
    }

    private void addPlayerNearbySceneChunkKeys(Set<String> visibleKeys)
    {
        WorldPoint location = getCurrentScenePlayerLocation();
        if (location == null)
        {
            return;
        }

        int regionX = location.getX() >> 6;
        int regionY = location.getY() >> 6;
        int plane = location.getPlane();

        for (int dx = -1; dx <= 1; dx++)
        {
            for (int dy = -1; dy <= 1; dy++)
            {
                int rx = regionX + dx;
                int ry = regionY + dy;
                if (rx >= 0 && ry >= 0)
                {
                    visibleKeys.add(getSceneChunkKey(plane, (rx << 8) | ry));
                }
            }
        }
    }

    private void addLoadedSceneChunkKeys(WorldView worldView, Set<String> visibleKeys)
    {
        Scene scene = worldView.getScene();
        if (scene == null)
        {
            return;
        }

        Tile[][][] tiles = scene.getTiles();
        int plane = worldView.getPlane();
        if (tiles == null || plane < 0 || plane >= tiles.length)
        {
            return;
        }

        Tile[][] planeTiles = tiles[plane];
        if (planeTiles == null)
        {
            return;
        }

        for (Tile[] column : planeTiles)
        {
            if (column == null)
            {
                continue;
            }

            for (Tile tile : column)
            {
                if (tile == null || tile.getRenderLevel() != plane)
                {
                    continue;
                }

                addSceneTileChunkKey(visibleKeys, tile);
            }
        }
    }

    private void addSceneTileChunkKey(Set<String> visibleKeys, Tile tile)
    {
        WorldPoint worldLocation = tile.getWorldLocation();
        if (worldLocation != null)
        {
            visibleKeys.add(getSceneChunkKey(worldLocation.getPlane(), worldLocation.getRegionID()));
        }

        LocalPoint localLocation = tile.getLocalLocation();
        if (localLocation == null)
        {
            return;
        }

        WorldPoint instanceLocation = WorldPoint.fromLocalInstance(client, localLocation, tile.getPlane());
        if (instanceLocation != null)
        {
            visibleKeys.add(getSceneChunkKey(instanceLocation.getPlane(), instanceLocation.getRegionID()));
        }
    }

    private WorldPoint getCurrentScenePlayerLocation()
    {
        if (client.getLocalPlayer() == null)
        {
            return null;
        }

        WorldView worldView = client.getTopLevelWorldView();
        LocalPoint localLocation = client.getLocalPlayer().getLocalLocation();
        if (worldView != null && localLocation != null)
        {
            WorldPoint sceneLocation = resolveSceneWorldLocation(worldView, localLocation, worldView.getPlane());
            if (sceneLocation != null)
            {
                return sceneLocation;
            }
        }

        return client.getLocalPlayer().getWorldLocation();
    }

    private WorldPoint resolveSceneWorldLocation(WorldView worldView, LocalPoint localLocation, int plane)
    {
        Scene scene = worldView.getScene();
        if (scene != null)
        {
            Tile[][][] tiles = scene.getTiles();
            int sceneX = localLocation.getSceneX();
            int sceneY = localLocation.getSceneY();
            if (tiles != null
                && plane >= 0
                && plane < tiles.length
                && tiles[plane] != null
                && sceneX >= 0
                && sceneX < tiles[plane].length
                && tiles[plane][sceneX] != null
                && sceneY >= 0
                && sceneY < tiles[plane][sceneX].length)
            {
                Tile tile = tiles[plane][sceneX][sceneY];
                if (tile != null)
                {
                    WorldPoint worldLocation = tile.getWorldLocation();
                    if (worldLocation != null)
                    {
                        return worldLocation;
                    }
                }
            }
        }

        return WorldPoint.fromLocalInstance(client, localLocation, plane);
    }

    private int extractSceneChunkPlane(String key)
    {
        if (key == null || !key.startsWith(SCENE_PREFIX))
        {
            return 0;
        }

        int separatorIndex = key.indexOf('.', SCENE_PREFIX.length());
        if (separatorIndex < 0)
        {
            return 0;
        }

        try
        {
            return Integer.parseInt(key.substring(SCENE_PREFIX.length(), separatorIndex));
        }
        catch (NumberFormatException ex)
        {
            return 0;
        }
    }

    private Point toSceneCanvasPoint(int plane, int worldX, int worldY, int offsetX, int offsetY)
    {
        return toSceneCanvasPoint(client.getTopLevelWorldView(), plane, worldX, worldY, offsetX, offsetY);
    }

    static int clampBrushSize(int brushSize)
    {
        if (brushSize < MIN_BRUSH_SIZE)
        {
            return MIN_BRUSH_SIZE;
        }

        return Math.min(brushSize, MAX_BRUSH_SIZE);
    }

    private Point toSceneCanvasPoint(WorldView worldView, int plane, int worldX, int worldY, int offsetX, int offsetY)
    {
        if (worldView == null)
        {
            return null;
        }

        LocalPoint tileCenter = sceneLocalPoint(worldView, plane, worldX, worldY);
        if (tileCenter == null)
        {
            return null;
        }

        Polygon tilePoly = Perspective.getCanvasTilePoly(client, tileCenter);
        if (tilePoly != null && tilePoly.npoints == 4)
        {
            return interpolateTileCanvasPoint(tilePoly, offsetX, offsetY);
        }

        LocalPoint localPoint = tileCenter.plus(offsetX - 64, offsetY - 64);
        return Perspective.localToCanvas(client, localPoint, plane);
    }

    private LocalPoint sceneLocalPoint(WorldView worldView, int plane, int worldX, int worldY)
    {
        LocalPoint localPoint = LocalPoint.fromWorld(worldView, worldX, worldY);
        if (localPoint != null)
        {
            return localPoint;
        }

        WorldPoint worldPoint = new WorldPoint(worldX, worldY, plane);
        for (WorldPoint instancePoint : WorldPoint.toLocalInstance(worldView, worldPoint))
        {
            if (instancePoint.getPlane() != plane)
            {
                continue;
            }

            localPoint = LocalPoint.fromWorld(worldView, instancePoint);
            if (localPoint != null)
            {
                return localPoint;
            }
        }

        return null;
    }

    private Point toSceneCanvasPoint(WorldView worldView, int plane, double continuousX, double continuousY)
    {
        int worldX = (int) Math.floor(continuousX + 0.5);
        int worldY = (int) Math.floor(continuousY + 0.5);
        int offsetX = clampOffset((int) Math.round((continuousX - worldX) * 128.0 + 64.0));
        int offsetY = clampOffset((int) Math.round((continuousY - worldY) * 128.0 + 64.0));
        return toSceneCanvasPoint(worldView, plane, worldX, worldY, offsetX, offsetY);
    }

    private static Point interpolateTileCanvasPoint(Polygon polygon, int offsetX, int offsetY)
    {
        double u = offsetY / 128.0;
        double v = offsetX / 128.0;
        int x = (int) Math.round(bilerp(
            polygon.xpoints[0],
            polygon.xpoints[1],
            polygon.xpoints[2],
            polygon.xpoints[3],
            u,
            v,
            true));
        int y = (int) Math.round(bilerp(
            polygon.ypoints[0],
            polygon.ypoints[1],
            polygon.ypoints[2],
            polygon.ypoints[3],
            u,
            v,
            false));
        return new Point(x, y);
    }

    private Tile findSceneTileAtMouse(WorldView worldView, int mouseX, int mouseY)
    {
        Tile selectedTile = client.getSelectedSceneTile();
        if (selectedTile != null
            && selectedTile.getRenderLevel() == worldView.getPlane()
            && chooseCloserContainingTile(null, selectedTile, mouseX, mouseY, Double.MAX_VALUE) == selectedTile)
        {
            return selectedTile;
        }

        Tile nearby = findNearbySceneTileAtMouse(worldView, mouseX, mouseY);
        if (nearby != null)
        {
            return nearby;
        }
        return findAnySceneTileAtMouse(worldView, mouseX, mouseY);
    }

    private Tile findNearbySceneTileAtMouse(WorldView worldView, int mouseX, int mouseY)
    {
        if (lastSceneSearchTarget == null)
        {
            return null;
        }

        Scene scene = worldView.getScene();
        if (scene == null)
        {
            return null;
        }

        Tile[][][] tiles = scene.getTiles();
        int currentRenderLevel = worldView.getPlane();
        if (tiles == null || currentRenderLevel < 0 || currentRenderLevel >= tiles.length)
        {
            return null;
        }

        Tile[][] planeTiles = tiles[currentRenderLevel];
        if (planeTiles == null)
        {
            return null;
        }

        int anchorSceneX = lastSceneSearchTarget.worldX - worldView.getBaseX();
        int anchorSceneY = lastSceneSearchTarget.worldY - worldView.getBaseY();
        int minSceneX = Math.max(0, anchorSceneX - 6);
        int maxSceneX = Math.min(planeTiles.length - 1, anchorSceneX + 6);
        if (minSceneX > maxSceneX)
        {
            return null;
        }

        Tile bestTile = null;
        double bestDistanceSquared = Double.MAX_VALUE;
        for (int sceneX = minSceneX; sceneX <= maxSceneX; sceneX++)
        {
            Tile[] column = planeTiles[sceneX];
            if (column == null)
            {
                continue;
            }

            int minSceneY = Math.max(0, anchorSceneY - 6);
            int maxSceneY = Math.min(column.length - 1, anchorSceneY + 6);
            for (int sceneY = minSceneY; sceneY <= maxSceneY; sceneY++)
            {
                Tile tile = column[sceneY];
                if (tile == null || tile.getRenderLevel() != currentRenderLevel)
                {
                    continue;
                }

                bestTile = chooseCloserContainingTile(bestTile, tile, mouseX, mouseY, bestDistanceSquared);
                if (bestTile == tile)
                {
                    bestDistanceSquared = distanceSquaredToTileCenter(tile, mouseX, mouseY);
                }
            }
        }

        return bestTile;
    }

    private Tile chooseCloserContainingTile(Tile currentBest, Tile candidate, int mouseX, int mouseY, double currentBestDistanceSquared)
    {
        LocalPoint localLocation = candidate.getLocalLocation();
        if (localLocation == null)
        {
            return currentBest;
        }

        Polygon polygon = Perspective.getCanvasTilePoly(client, localLocation);
        if (polygon == null || !polygon.contains(mouseX, mouseY))
        {
            return currentBest;
        }

        double candidateDistanceSquared = distanceSquaredToTileCenter(candidate, mouseX, mouseY);
        return candidateDistanceSquared < currentBestDistanceSquared ? candidate : currentBest;
    }

    private Tile findAnySceneTileAtMouse(WorldView worldView, int mouseX, int mouseY)
    {
        Scene scene = worldView.getScene();
        if (scene == null)
        {
            return null;
        }

        Tile[][][] tiles = scene.getTiles();
        int currentRenderLevel = worldView.getPlane();
        if (tiles == null || currentRenderLevel < 0 || currentRenderLevel >= tiles.length)
        {
            return null;
        }

        Tile[][] planeTiles = tiles[currentRenderLevel];
        if (planeTiles == null)
        {
            return null;
        }

        Tile bestTile = null;
        double bestDistanceSquared = Double.MAX_VALUE;
        for (Tile[] column : planeTiles)
        {
            if (column == null)
            {
                continue;
            }

            for (Tile tile : column)
            {
                if (tile == null || tile.getRenderLevel() != currentRenderLevel)
                {
                    continue;
                }

                bestTile = chooseCloserContainingTile(bestTile, tile, mouseX, mouseY, bestDistanceSquared);
                if (bestTile == tile)
                {
                    bestDistanceSquared = distanceSquaredToTileCenter(tile, mouseX, mouseY);
                }
            }
        }
        return bestTile;
    }

    private double distanceSquaredToTileCenter(Tile tile, int mouseX, int mouseY)
    {
        LocalPoint localLocation = tile.getLocalLocation();
        if (localLocation == null)
        {
            return Double.MAX_VALUE;
        }

        Polygon polygon = Perspective.getCanvasTilePoly(client, localLocation);
        if (polygon == null)
        {
            return Double.MAX_VALUE;
        }

        Rectangle bounds = polygon.getBounds();
        double centerX = bounds.getCenterX();
        double centerY = bounds.getCenterY();
        double dx = centerX - mouseX;
        double dy = centerY - mouseY;
        return dx * dx + dy * dy;
    }

    private static boolean isLeftButtonDown(MouseEvent event)
    {
        return (event.getModifiersEx() & MouseEvent.BUTTON1_DOWN_MASK) != 0
            || event.getButton() == MouseEvent.BUTTON1
            || SwingUtilities.isLeftMouseButton(event);
    }

    private boolean isCanvasEvent(MouseEvent event)
    {
        if (event == null || client.getCanvas() == null)
        {
            return false;
        }

        if (event.getComponent() == client.getCanvas())
        {
            return true;
        }

        java.awt.Point point = event.getPoint();
        return point != null
            && point.x >= 0
            && point.y >= 0
            && point.x < client.getCanvas().getWidth()
            && point.y < client.getCanvas().getHeight();
    }

    private static PaintPoint interpolatePoint(double startX, double startY, double endX, double endY, double t)
    {
        return pointFromContinuous(
            startX + (endX - startX) * t,
            startY + (endY - startY) * t);
    }

    private static PaintPoint pointFromContinuous(double continuousX, double continuousY)
    {
        PaintPoint point = new PaintPoint();
        point.worldX = (int) Math.floor(continuousX + 0.5);
        point.worldY = (int) Math.floor(continuousY + 0.5);
        point.offsetX = clampOffset((int) Math.round((continuousX - point.worldX) * 128.0 + 64.0));
        point.offsetY = clampOffset((int) Math.round((continuousY - point.worldY) * 128.0 + 64.0));
        return point;
    }

