    public void segmentWithinCanvasRadiusHitsMidpoint()
    {
        assertTrue(PaintMath.segmentWithinCanvasRadius(new Point(10, 10), new Point(30, 10), 20, 14, 4));
    }

    @Test
    public void segmentWithinCanvasRadiusRejectsDistantPoint()
    {
        assertTrue(!PaintMath.segmentWithinCanvasRadius(new Point(10, 10), new Point(30, 10), 20, 20, 4));
    }

    @Test
    public void cursorSweepIntersectsCrossingStrokeSegment()
    {
        assertTrue(PaintMath.segmentsWithinCanvasRadius(
            new Point(10, 20),
            new Point(30, 20),
            20,
            0,
            20,
            40,
            1));
    }

    @Test
    public void cursorSweepRejectsDistantStrokeSegment()
    {
        assertTrue(!PaintMath.segmentsWithinCanvasRadius(
            new Point(10, 20),
            new Point(30, 20),
            20,
            40,
            20,
            60,
            3));
    }

    @Test
    public void cursorSweepHitsExpandedRectangle()
    {
        Rectangle2D bounds = new Rectangle2D.Double(20, 20, 20, 20);

        assertTrue(PaintMath.rectangleWithinCanvasSweep(bounds, 0, 15, 60, 15, 5));
        assertTrue(!PaintMath.rectangleWithinCanvasSweep(bounds, 0, 10, 60, 10, 5));
    }

    @Test
    public void textWithinCanvasRadiusHitsAcrossRenderedBounds()
    {
        Font font = new Font("Dialog", Font.PLAIN, 16);
        Point baseline = new Point(100, 100);

        assertTrue(PaintMath.textWithinCanvasRadius(baseline, font, "Hello", 110, 96, 3));
        assertTrue(PaintMath.textWithinCanvasRadius(baseline, font, "Hello", 132, 100, 3));
    }

    @Test
    public void textWithinCanvasRadiusRejectsDistantPoint()
    {
        Font font = new Font("Dialog", Font.PLAIN, 16);
        Point baseline = new Point(100, 100);

        assertTrue(!PaintMath.textWithinCanvasRadius(baseline, font, "Hello", 40, 40, 3));
    }

    @Test
    public void textBoundsIncludeOnePixelShadowOffset()
    {
        Font font = new Font("Dialog", Font.BOLD, 16);
        Point baseline = new Point(100, 100);
        String text = "!! Warning Bring Antifire !!";
        FontRenderContext frc = new FontRenderContext(null, true, true);
        GlyphVector glyphVector = font.createGlyphVector(frc, text);
        Rectangle expected = glyphVector.getPixelBounds(frc, baseline.getX(), baseline.getY())
            .union(glyphVector.getPixelBounds(frc, baseline.getX() + 1, baseline.getY() + 1));

        Rectangle2D bounds = PaintMath.textBounds(baseline, font, text);

        assertNotNull(bounds);
        assertEquals(expected.getX(), bounds.getX(), 0.0);
        assertEquals(expected.getY(), bounds.getY(), 0.0);
        assertEquals(expected.getWidth(), bounds.getWidth(), 0.0);
        assertEquals(expected.getHeight(), bounds.getHeight(), 0.0);
    }

    @Test
    public void shapeOutlineSupportsAllShapeTypes()
    {
        Point center = new Point(100, 100);

        for (PaintShapeType shapeType : PaintShapeType.values())
        {
            Shape outline = PaintMath.shapeOutline(center, 40, shapeType);
            assertNotNull(outline);
            assertTrue(outline.getBounds2D().getWidth() > 0.0
                || outline.getBounds2D().getHeight() > 0.0);
        }
    }
}

package com.paintoverlays;

import java.awt.Color;
import java.lang.reflect.Field;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class PaintOverlaysPluginStatusTest
{
    @Test
    public void unloadedKnownChunkDoesNotPretendToHaveZeroUsage()
    {
        assertEquals(
            "Chunk scene.0.1234 | Stored paint",
            PaintOverlaysPlugin.formatChunkUsageStatus("Chunk", "scene.0.1234", null, true));
    }

    @Test
    public void loadedChunkShowsCurrentUsageCounts()
    {
        PaintChunkData chunk = new PaintChunkData();
        PaintStroke stroke = new PaintStroke(0, new Color(0x26FF00), 4);
        stroke.points.add(new PaintPoint(new PaintTarget(3200, 3200, 0, 64, 64)));
        chunk.strokes.add(stroke);
        chunk.shapes.add(new PaintShape(
            new PaintTarget(3201, 3201, 0, 64, 64),
            new Color(0xFF0000),
            48,
            PaintShapeType.STAR));
        chunk.stamps.add(new PaintStamp(
            new PaintTarget(3201, 3202, 0, 64, 64),
            48,
            PaintStampType.CHICKEN));
        chunk.texts.add(new PaintText(
            new PaintTarget(3202, 3202, 0, 64, 64),
            new Color(0x26FF00),
            16,
            PaintFontStyle.RUNE_SCAPE,
            new Color(0, 0, 0, 96),
            new Color(255, 255, 255, 180),
            "Hello"));

        assertEquals(
            "Chunk scene.0.1234 | Brush 1/300 | Shapes 1/100 | Stamps 1/100 | Text 1/100",
            PaintOverlaysPlugin.formatChunkUsageStatus("Chunk", "scene.0.1234", chunk, true));
    }

    @Test
    public void inputStatusHidesChunkUsageWhenDebugToolsDisabled() throws Exception
    {
        String previous = System.getProperty("paintoverlays.debugTools");
        System.clearProperty("paintoverlays.debugTools");
        try
        {
            PaintOverlaysPlugin plugin = new PaintOverlaysPlugin();
            setField(plugin, "cachedSceneStatusChunkKey", "scene.0.1234");

            assertEquals("Off", plugin.getInputStatusText());
        }
        finally
        {
            restoreDebugProperty(previous);
        }
    }

    @Test
    public void inputStatusIncludesChunkUsageWhenDebugToolsEnabled() throws Exception
    {
        String previous = System.getProperty("paintoverlays.debugTools");
        System.setProperty("paintoverlays.debugTools", "true");
        try
        {
            PaintOverlaysPlugin plugin = new PaintOverlaysPlugin();
            setField(plugin, "cachedSceneStatusChunkKey", "scene.0.1234");

            String status = plugin.getInputStatusText();
            assertTrue(status.startsWith("Off | Chunk scene.0.1234"));
        }
        finally
        {
            restoreDebugProperty(previous);
        }
    }

    private static void setField(Object target, String fieldName, Object value) throws Exception
    {
        Field field = PaintOverlaysPlugin.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    private static void restoreDebugProperty(String previous)
    {
        if (previous == null)
        {
            System.clearProperty("paintoverlays.debugTools");
        }
        else
        {
            System.setProperty("paintoverlays.debugTools", previous);
        }
    }
}

