package com.paintoverlays;

import com.google.gson.Gson;
import java.awt.Color;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class PaintPersistenceTest
{
    private static final Gson GSON = new Gson();

    @Test
    public void legacyDisabledDecorationsMigrateToTransparentAndStayThatWay()
    {
        String legacyJson = "{"
            + "\"strokes\":[],"
            + "\"shapes\":[],"
            + "\"texts\":[{"
            + "\"plane\":0,"
            + "\"worldX\":3200,"
            + "\"worldY\":3200,"
            + "\"offsetX\":64,"
            + "\"offsetY\":64,"
            + "\"colorArgb\":" + new Color(0x26FF00).getRGB() + ","
            + "\"fontSize\":16,"
            + "\"fontStyle\":\"RUNE_SCAPE\","
            + "\"backgroundEnabled\":false,"
            + "\"backgroundColorArgb\":" + new Color(0, 0, 0, 128).getRGB() + ","
            + "\"borderEnabled\":false,"
            + "\"borderColorArgb\":" + new Color(255, 255, 255, 255).getRGB() + ","
            + "\"text\":\"Legacy\""
            + "}]"
            + "}";

        PaintChunkData chunk = GSON.fromJson(legacyJson, PaintChunkData.class);
        chunk.normalizeLoadedState();

        PaintText text = chunk.texts.get(0);
        assertEquals(0, new Color(text.backgroundColorArgb, true).getAlpha());
        assertEquals(0, new Color(text.borderColorArgb, true).getAlpha());
        assertFalse(text.backgroundEnabled);
        assertFalse(text.borderEnabled);

        PaintChunkData reloaded = GSON.fromJson(GSON.toJson(chunk), PaintChunkData.class);
        reloaded.normalizeLoadedState();

        PaintText persisted = reloaded.texts.get(0);
        assertEquals(0, new Color(persisted.backgroundColorArgb, true).getAlpha());
        assertEquals(0, new Color(persisted.borderColorArgb, true).getAlpha());
        assertFalse(persisted.backgroundEnabled);
        assertFalse(persisted.borderEnabled);
    }

    @Test
    public void alphaBasedDecorationsPersistAcrossJsonRoundTrip()
    {
        PaintChunkData chunk = new PaintChunkData();
        chunk.texts.add(new PaintText(
            new PaintTarget(3200, 3200, 0, 64, 64),
            new Color(0x26FF00),
            16,
            PaintFontStyle.RUNE_SCAPE,
            new Color(0, 0, 0, 96),
            new Color(255, 255, 255, 180),
            "Hello"));

        PaintChunkData reloaded = GSON.fromJson(GSON.toJson(chunk), PaintChunkData.class);
        reloaded.normalizeLoadedState();

        PaintText text = reloaded.texts.get(0);
        assertEquals(96, new Color(text.backgroundColorArgb, true).getAlpha());
        assertEquals(180, new Color(text.borderColorArgb, true).getAlpha());
        assertTrue(text.backgroundEnabled);
        assertTrue(text.borderEnabled);
    }

    @Test
    public void loadedTextUsesAuthoredSanitizationRules()
    {
        String source = "A\nB\t" + String.join("", java.util.Collections.nCopies(100, "x")) + "\u0007";
        PaintChunkData chunk = new PaintChunkData();
        chunk.texts.add(new PaintText(
            new PaintTarget(3200, 3200, 0, 64, 64),
            Color.WHITE,
            16,
            PaintFontStyle.RUNE_SCAPE,
            Color.BLACK,
            Color.WHITE,
            source));

        PaintChunkData reloaded = GSON.fromJson(GSON.toJson(chunk), PaintChunkData.class);
        reloaded.normalizeLoadedState();

        assertEquals(PaintMath.sanitizePendingText(source), reloaded.texts.get(0).text);
        assertEquals(PaintMath.MAX_TEXT_LENGTH, reloaded.texts.get(0).text.length());
    }

    @Test
    public void unsupportedStampTypesCanBePreservedForFallbackRendering()
    {
        String legacyJson = "{"
            + "\"strokes\":[],"
            + "\"shapes\":[],"
            + "\"stamps\":[{"
            + "\"plane\":0,"
            + "\"worldX\":3200,"
            + "\"worldY\":3200,"
            + "\"offsetX\":64,"
            + "\"offsetY\":64,"
            + "\"size\":40,"
            + "\"stampType\":\"OLD_REMOVED_STAMP\""
            + "}],"
            + "\"texts\":[]"
            + "}";

        PaintChunkData chunk = GSON.fromJson(legacyJson, PaintChunkData.class);
        assertEquals(1, chunk.stamps.size());
        chunk.stamps.get(0).unsupportedStampType = "OLD_REMOVED_STAMP";
        chunk.stamps.removeIf(stamp -> stamp == null
            || (stamp.stampType == null && (stamp.unsupportedStampType == null || stamp.unsupportedStampType.trim().isEmpty()))
            || stamp.size < 4);

        assertEquals(1, chunk.stamps.size());
        assertEquals("OLD_REMOVED_STAMP", chunk.stamps.get(0).unsupportedStampType);
        assertFalse(chunk.isEmpty());
    }
}

package com.paintoverlays;

import com.google.gson.Gson;
import java.awt.Color;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class PaintUndoTest
{
    private static final Gson GSON = new Gson();

    @Test
    public void undoActionDeduplicatesSnapshotsPerChunk()
    {
        PaintUndoAction undoAction = new PaintUndoAction("profile");

        undoAction.addSnapshot("scene.0.1234", "{\"texts\":[]}");
        undoAction.addSnapshot("scene.0.1234", "{\"texts\":[1]}");
        undoAction.addSnapshot("map.5678", null);

        assertEquals(2, undoAction.snapshots.size());
        assertTrue(undoAction.hasSnapshot("scene.0.1234"));
        assertTrue(undoAction.hasSnapshot("map.5678"));
    }

    @Test
    public void snapshotJsonRestoresPreMutationChunkState()
    {
        PaintChunkData original = new PaintChunkData();
        original.texts.add(new PaintText(
            new PaintTarget(3200, 3200, 0, 64, 64),
            new Color(0x26FF00),
            16,
            PaintFontStyle.RUNE_SCAPE,
            new Color(0, 0, 0, 96),
            new Color(255, 255, 255, 180),
            "Before"));

        String snapshotJson = GSON.toJson(original);

        PaintChunkData mutated = GSON.fromJson(snapshotJson, PaintChunkData.class);
        assertNotNull(mutated);
        mutated.texts.clear();
        mutated.shapes.add(new PaintShape(
            new PaintTarget(3210, 3210, 0, 64, 64),
            new Color(0xFF0000),
            48,
            PaintShapeType.STAR));

        PaintChunkData restored = GSON.fromJson(snapshotJson, PaintChunkData.class);
        restored.normalizeLoadedState();

        assertEquals(1, restored.texts.size());
        assertEquals(0, restored.shapes.size());
        assertEquals("Before", restored.texts.get(0).text);
        assertEquals(96, new Color(restored.texts.get(0).backgroundColorArgb, true).getAlpha());
        assertFalse(restored.isEmpty());
    }
}

package com.paintoverlays;

import java.awt.Rectangle;
import net.runelite.api.Point;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class PaintWorldMapViewStateTest
{
    @Test
    public void containsCanvasPointRejectsOverviewAndSelectorAreas()
    {
        PaintWorldMapViewState state = PaintWorldMapViewState.of(
            new Rectangle(20, 30, 300, 200),
            new Rectangle(20, 30, 40, 40),
            new Rectangle(260, 30, 60, 30),
            4.0f,
            new Point(3200, 3200));

        assertTrue(state.containsCanvasPoint(120, 120));
        assertFalse(state.containsCanvasPoint(30, 40));
        assertFalse(state.containsCanvasPoint(280, 40));
        assertFalse(state.containsCanvasPoint(5, 5));
    }

    @Test
    public void targetLookupUsesSameClipRules()
    {
        PaintWorldMapViewState state = PaintWorldMapViewState.of(
            new Rectangle(20, 30, 300, 200),
            new Rectangle(20, 30, 40, 40),
            null,
            3.0f,
            new Point(3200, 3200));

        assertNull(state.getTarget(25, 35));
        assertNotNull(state.getTarget(120, 120));
    }

    @Test
    public void eraserSweepCannotCrossExcludedMapControls()
    {
        PaintWorldMapViewState state = PaintWorldMapViewState.of(
            new Rectangle(0, 0, 200, 200),
            new Rectangle(80, 80, 40, 40),
            null,
            3.0f,
            new Point(3200, 3200));

        assertTrue(state.canSweepBetweenCanvasPoints(40, 50, 160, 50));
        assertFalse(state.canSweepBetweenCanvasPoints(40, 100, 160, 100));
        assertFalse(state.canSweepBetweenCanvasPoints(40, 100, 100, 100));
    }

    @Test
    public void eraserRadiusCannotReachBehindExcludedMapControls()
    {
        PaintWorldMapViewState state = PaintWorldMapViewState.of(
            new Rectangle(0, 0, 200, 200),
            new Rectangle(80, 80, 40, 40),
            null,
            3.0f,
            new Point(3200, 3200));

        assertTrue(state.canEraseBetweenCanvasPoints(30, 70, 170, 70, 5));
        assertFalse(state.canEraseBetweenCanvasPoints(30, 70, 170, 70, 15));
        assertFalse(state.canEraseBetweenCanvasPoints(70, 100, 70, 100, 15));
    }

    @Test
    public void visibleRegionIdsAreComputedForAvailableState()
    {
        PaintWorldMapViewState state = PaintWorldMapViewState.of(
            new Rectangle(20, 30, 300, 200),
            null,
            null,
            4.0f,
            new Point(3200, 3200));

        assertFalse(state.getVisibleRegionIds().isEmpty());
    }

    @Test
    public void matchesOnlyEquivalentViewInputs()
    {
        Rectangle bounds = new Rectangle(20, 30, 300, 200);
        Rectangle overview = new Rectangle(20, 30, 40, 40);
        Point center = new Point(3200, 3200);
        PaintWorldMapViewState state = PaintWorldMapViewState.of(bounds, overview, null, 4.0f, center);

        assertTrue(state.matches(new Rectangle(bounds), new Rectangle(overview), null, 4.0f, new Point(3200, 3200)));
        assertFalse(state.matches(bounds, overview, null, 4.0f, new Point(3201, 3200)));
        assertFalse(state.matches(bounds, overview, null, 3.0f, center));
    }
}
